class Solution {
    int preIdx;
    unordered_map<int, int> postIdx;
public:
    TreeNode* constructFromPrePost(vector<int>& preorder, vector<int>& postorder) {
        preIdx = 0;
        postIdx.clear();
        for (int i = 0; i < (int)postorder.size(); i++)
            postIdx[postorder[i]] = i;
        return build(preorder, 0, (int)postorder.size() - 1);
    }
private:
    TreeNode* build(vector<int>& pre, int postStart, int postEnd) {
        if (postStart > postEnd) return nullptr;
        TreeNode* root = new TreeNode(pre[preIdx++]);
        if (postStart == postEnd) return root;
        int idx = postIdx[pre[preIdx]];
        root->left  = build(pre, postStart, idx);
        root->right = build(pre, idx + 1, postEnd - 1);
        return root;
    }
};
